const nowUtc = new Date();
const pktHour = (nowUtc.getUTCHours() + 5) % 24;
let window = 'post_market';
let windowLabel = 'Post-Market Recap';
let alertWindow = 'POST_MARKET';
if (pktHour >= 7 && pktHour < 11) {
  window = 'pre_market'; windowLabel = 'Pre-Market Outlook'; alertWindow = 'PRE_MARKET';
} else if (pktHour >= 11 && pktHour < 16) {
  window = 'mid_session'; windowLabel = 'Mid-Session Update'; alertWindow = 'MID_SESSION';
}
return [{ json: { window, window_label: windowLabel, alert_window: alertWindow, fired_at: nowUtc.toISOString() } }];

/*
 * Join holdings × signals on ticker. Filter by:
 *   - window preference (user opted into THIS time slot)
 *   - at least one channel enabled
 *
 * Throws with diagnostic context if filtering yields zero output,
 * so the n8n UI shows exactly which step rejected the data instead
 * of the generic 'No output data returned' halt. */
const holdings = $('Fetch all holdings (+ users + prefs)').all().map(i => i.json);
const signals = $('Fetch SELL/STRONG_SELL signals').all().map(i => i.json);
const windowCtx = $('Detect window').first().json;
const window = windowCtx.window;

const signalByTicker = {};
for (const s of signals) signalByTicker[s.ticker] = s;

const rejectReasons = { no_ticker: 0, no_signal: 0, no_prefs: 0, window_off: 0, no_channels: 0 };

const byTicker = {};
for (const h of holdings) {
  const ticker = h.symbol && h.symbol.ticker;
  if (!ticker) { rejectReasons.no_ticker++; continue; }
  const sig = signalByTicker[ticker];
  if (!sig) { rejectReasons.no_signal++; continue; }
  const user = h.user || {};
  // PostgREST returns notification_preferences as either an array
  // (one-to-many) or a single object (one-to-one, when FK has unique
  // constraint). Handle both.
  const prefsRaw = user.notification_preferences;
  let prefs;
  if (Array.isArray(prefsRaw)) {
    if (prefsRaw.length === 0) { rejectReasons.no_prefs++; continue; }
    prefs = prefsRaw[0];
  } else if (prefsRaw && typeof prefsRaw === 'object') {
    prefs = prefsRaw;
  } else {
    rejectReasons.no_prefs++; continue;
  }
  if (!prefs[window]) { rejectReasons.window_off++; continue; }
  if (!prefs.email_enabled && !prefs.slack_enabled) { rejectReasons.no_channels++; continue; }

  (byTicker[ticker] = byTicker[ticker] || { signal: sig, holders: [] }).holders.push({
    user, prefs,
    holding: { id: h.id, quantity: h.quantity, avg_buy_price: h.avg_buy_price },
  });
}

if (Object.keys(byTicker).length === 0) {
  throw new Error('Workflow B join produced 0 tickers. Diagnostics: ' + JSON.stringify({
    holdings_count: holdings.length,
    signals_count: signals.length,
    window: window,
    holding_tickers: holdings.map(h => h.symbol && h.symbol.ticker).filter(Boolean),
    signal_tickers: signals.map(s => s.ticker),
    reject_reasons: rejectReasons,
    sample_holding_user_prefs: holdings[0] && holdings[0].user && holdings[0].user.notification_preferences,
  }));
}

return Object.entries(byTicker).map(([ticker, ctx]) => ({
  json: {
    ticker,
    ...ctx.signal,
    audience: ctx.holders,
    window: windowCtx.window,
    window_label: windowCtx.window_label,
    alert_window: windowCtx.alert_window,
  },
}));

const signals = $('Join + fan out per ticker').all().map(i => i.json);
if (signals.length === 0) return [];
let lives = [];
let newsAll = [];
try { lives = $('Fetch live_market_data').all().map(i => i.json); } catch (e) {}
try { newsAll = $('Fetch top 2 news').all().map(i => i.json); } catch (e) {}
const liveByTicker = {};
for (const l of lives) liveByTicker[l.ticker] = l;
const newsByTicker = {};
for (const n of newsAll) {
  (newsByTicker[n.ticker] = newsByTicker[n.ticker] || []).push(n);
}

// Build per-ticker Gemini body server-side so the HTTP node can pass
// it as a single clean JSON.stringify — embedded JSON.stringify in
// the jsonBody template double-escapes badly.
return signals.map(s => {
  const live = liveByTicker[s.ticker] || {};
  const news = newsByTicker[s.ticker] || [];

  const userContent = `User HOLDS: ${s.ticker}\nSignal: ${s.signal} (confidence: ${s.suggestion_confidence})\nHealth: ${s.health_label}\nHorizon: ${s.horizon}d\nReason: ${s.reason}\nDominant news sentiment: ${s.dominant_sentiment}\nContributions: ${JSON.stringify(s.contributions)}\n\nCurrent: close = ${live.close}, change = ${live.change_pct}%, RSI14 = ${live.rsi14}, MA20 = ${live.ma20}, MA50 = ${live.ma50}, MA200 = ${live.ma200}, volatility20d = ${live.volatility20d}, volume_ratio = ${live.volume_ratio}, EPS = ${live.eps}.\n\nTop news:\n- ${(news[0] && news[0].headline) || 'none'}\n- ${(news[1] && news[1].headline) || 'none'}\n\nWrite the explanation addressed to the holder. Weave the specific numbers into your reasoning. End with a confident, direct action (no risk warnings or 'consider consulting' lines).`;

  const geminiBody = {
    systemInstruction: {
      parts: [{ text: "You are FinMate writing for an investor who already OWNS this stock. The signal is on their existing position. Write a confident, friendly 5-7 sentence explanation. Translate technical terms into meaning, don't define them. Cite specific numbers (current price, % change, RSI level, MA position, volume vs 20-day average, EPS if relevant, and the holder's P&L) to ground the recommendation. Mention news context if relevant. Be direct — DO NOT add disclaimers, risk warnings, hedging, 'consult an advisor' lines, or 'this is not financial advice' caveats. End with a direct, practical action." }],
    },
    contents: [{ role: 'user', parts: [{ text: userContent }] }],
    generationConfig: { maxOutputTokens: 1500, temperature: 0.7, thinkingConfig: { thinkingBudget: 0 } },
  };

  return { json: { ...s, live, news, gemini_body: geminiBody } };
});

/* Build HTML + Slack payload per (holder × channel). Each holder gets
 * their own qty + P&L computed from current price. Each row carries
 * user_id and ticker so the next node creates a per-holder Alert row. */
const src = $('Join context per ticker').item.json;
const llmResp = $input.item.json;
const plainEnglish = llmResp?.candidates?.[0]?.content?.parts?.[0]?.text || src.reason;

const ticker = src.ticker;
const signalLabel = src.signal.replace('_', ' ');
const signal3 = 'SELL';
const color = '#dc2626';
const arrow = '▼';
const windowLabel = src.window_label;
const alertWindow = src.alert_window;

const live = src.live || {};
const news = src.news || [];

const safeNum = (v, d = 2) => (v != null && !isNaN(v) ? Number(v).toFixed(d) : '—');
const pct = live.change_pct != null ? Number(live.change_pct) : 0;
const pctSign = pct >= 0 ? '+' : '';

const newsHtml = news.length
  ? news.map(n => `<li style=\"margin: 4px 0;\"><a href=\"${n.link}\" style=\"color: #2563eb; text-decoration: none;\">${n.headline}</a> <span style=\"color: #6b7280; font-size: 12px;\">· ${n.source} · ${n.sentiment}</span></li>`).join('')
  : '<li style=\"color: #6b7280;\">No recent news</li>';

const nowIso = new Date().toISOString();
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });

// Per-holder payload — qty/avgBuy/pnl varies. buildIds is called inside
// the loop with the holder's specific payload.
const symbols = [ticker];
const seenUsers = new Set();

const buildIds = (userId, holderPayload) => {
  const alertRowId = newUuid();
  const alertDetailId = newUuid();
  const notificationId = newUuid();
  const alertLogId = newUuid();
  return {
    alert_row_id: alertRowId,
    alert_log_id: alertLogId,
    alert_detail_id: alertDetailId,
    notification_id: notificationId,
    now_iso: nowIso,
    symbols,
    create_alert_body: { id: alertRowId, user_id: userId, ticker, symbols, signal: signal3, reason: plainEnglish, alert_window: alertWindow, created_at: nowIso, updated_at: nowIso },
    create_alert_detail_body: { id: alertDetailId, alert_id: alertRowId, payload: holderPayload, created_at: nowIso, updated_at: nowIso },
    create_notification_body: { id: notificationId, user_id: userId, alert_id: alertRowId, type: 'POSITION_ALERT', category: 'stock', created_at: nowIso, updated_at: nowIso },
  };
};

const rows = [];
for (const h of (src.audience || [])) {
  const user = h.user;
  const prefs = h.prefs;
  const qty = Number(h.holding.quantity);
  const avgBuy = Number(h.holding.avg_buy_price);
  const cur = Number(live.close || avgBuy);
  const pnlPct = avgBuy ? ((cur - avgBuy) / avgBuy) * 100 : 0;
  const pnlPkr = (cur - avgBuy) * qty;
  const pnlColor = pnlPct >= 0 ? '#16a34a' : '#dc2626';
  const pnlSign = pnlPct >= 0 ? '+' : '';

  const holderPayload = {
    ticker, signal: src.signal, confidence: src.suggestion_confidence,
    qty, avg_buy: avgBuy, current: cur, pnl_pct: pnlPct, pnl_pkr: pnlPkr,
    close: live.close, change_pct: live.change_pct,
    rsi14: live.rsi14, ma50: live.ma50, ma200: live.ma200, volatility20d: live.volatility20d,
    news: (news || []).map(n => ({ headline: n.headline, link: n.link, source: n.source, sentiment: n.sentiment })),
    summary: plainEnglish, window_label: windowLabel, type: 'POSITION_ALERT',
  };

  const html = `
<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 560px; margin: 0 auto; padding: 24px; background: #ffffff; border: 1px solid #e5e7eb; border-radius: 12px;\">
  <div style=\"display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #f3f4f6; padding-bottom: 12px; margin-bottom: 16px;\">
    <h1 style=\"margin: 0; font-size: 22px; font-weight: 700; color: #1f2937;\">Fin<span style=\"color: #2563eb;\">Mate</span></h1>
    <span style=\"font-size: 12px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;\">Your Portfolio · ${windowLabel}</span>
  </div>
  <div style=\"background: #fef3c7; border-left: 4px solid #d97706; padding: 12px 16px; border-radius: 8px; margin-bottom: 16px; font-size: 14px; color: #92400e;\">
    <strong>Position alert</strong> — you hold this stock and our models recommend ${signalLabel.toLowerCase()}.
  </div>
  <div style=\"background: #f9fafb; border-radius: 10px; padding: 16px; margin-bottom: 16px;\">
    <div style=\"display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px;\">
      <h2 style=\"margin: 0; font-size: 28px; font-weight: 700; color: #1f2937;\">${ticker}</h2>
      <span style=\"font-size: 14px; font-weight: 600; color: ${color};\">${arrow} ${signalLabel}</span>
    </div>
    <div style=\"font-size: 14px; color: #4b5563;\">
      <strong style=\"color: #1f2937;\">PKR ${safeNum(cur)}</strong>
      &nbsp;·&nbsp; <span style=\"color: ${pct >= 0 ? '#16a34a' : '#dc2626'};\">${pctSign}${safeNum(pct)}% today</span>
      &nbsp;·&nbsp; confidence: <strong>${src.suggestion_confidence}</strong>
    </div>
  </div>
  <table style=\"width: 100%; font-size: 13px; color: #4b5563; border-collapse: collapse; margin-bottom: 16px;\">
    <tr style=\"background: #f3f4f6;\"><td colspan=\"4\" style=\"padding: 8px 12px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px; color: #6b7280; border-radius: 6px 6px 0 0;\">Your position</td></tr>
    <tr>
      <td style=\"padding: 8px 12px;\">Quantity</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>${qty}</strong></td>
      <td style=\"padding: 8px 12px;\">Avg buy price</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>PKR ${safeNum(avgBuy)}</strong></td>
    </tr>
    <tr style=\"background: #f9fafb;\">
      <td style=\"padding: 8px 12px; border-radius: 0 0 0 6px;\">Unrealised P&amp;L</td>
      <td style=\"padding: 8px 12px; text-align: right; color: ${pnlColor};\"><strong>${pnlSign}${safeNum(pnlPct)}%</strong></td>
      <td style=\"padding: 8px 12px;\">P&amp;L in PKR</td>
      <td style=\"padding: 8px 12px; text-align: right; color: ${pnlColor}; border-radius: 0 0 6px 0;\"><strong>${pnlSign}${safeNum(pnlPkr)}</strong></td>
    </tr>
  </table>
  <p style=\"font-size: 15px; line-height: 1.6; color: #374151; margin: 0 0 16px 0;\">${plainEnglish}</p>
  <table style=\"width: 100%; font-size: 13px; color: #4b5563; border-collapse: collapse; margin-bottom: 16px;\">
    <tr style=\"background: #f9fafb;\">
      <td style=\"padding: 8px 12px; border-radius: 6px 0 0 6px;\">RSI 14</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>${safeNum(live.rsi14, 1)}</strong></td>
      <td style=\"padding: 8px 12px;\">MA 50</td>
      <td style=\"padding: 8px 12px; text-align: right; border-radius: 0 6px 6px 0;\"><strong>${safeNum(live.ma50)}</strong></td>
    </tr>
    <tr>
      <td style=\"padding: 8px 12px;\">MA 200</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>${safeNum(live.ma200)}</strong></td>
      <td style=\"padding: 8px 12px;\">Volatility</td>
      <td style=\"padding: 8px 12px; text-align: right;\"><strong>${safeNum((live.volatility20d || 0) * 100, 1)}%</strong></td>
    </tr>
  </table>
  <h3 style=\"font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; color: #6b7280; margin: 0 0 8px 0;\">Recent news</h3>
  <ul style=\"list-style: none; padding-left: 0; margin: 0 0 20px 0; font-size: 14px;\">${newsHtml}</ul>
  <div style=\"border-top: 1px solid #f3f4f6; padding-top: 12px; font-size: 12px; color: #6b7280; text-align: center;\">
    Don't understand a number? <a href=\"https://finmate.app/docs/notifications\" style=\"color: #2563eb;\">Read the guide →</a><br>
    Sent by FinMate · ${new Date(src.generated_at).toLocaleString('en-PK', { timeZone: 'Asia/Karachi' })} PKT
  </div>
</div>`.trim();

  const plain = `Position alert: ${ticker} — ${signalLabel} (${src.suggestion_confidence})\n\nYou hold ${qty} @ PKR ${safeNum(avgBuy)} (P&L ${pnlSign}${safeNum(pnlPct)}%)\n\n${plainEnglish}\n\nDocs: https://finmate.app/docs/notifications`;

  const channels = [];
  if (prefs.email_enabled && user.email) {
    channels.push({
      channel: 'email', alert_log_id: newUuid(), to: user.email,
      subject: `Position alert — ${ticker} ${arrow} ${signalLabel}`,
      html, plain,
    });
  }
  if (prefs.slack_enabled && user.slack_webhook) {
    channels.push({
      channel: 'slack', alert_log_id: newUuid(), to: user.slack_webhook,
      slack_payload: {
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: `Position alert: ${ticker} ${arrow} ${signalLabel}` } },
          { type: 'section', fields: [
            { type: 'mrkdwn', text: `*Qty*\n${qty}` },
            { type: 'mrkdwn', text: `*Avg buy*\nPKR ${safeNum(avgBuy)}` },
            { type: 'mrkdwn', text: `*Current*\nPKR ${safeNum(cur)} (${pctSign}${safeNum(pct)}%)` },
            { type: 'mrkdwn', text: `*P&L*\n${pnlSign}${safeNum(pnlPct)}% (${pnlSign}PKR ${safeNum(pnlPkr)})` },
          ] },
          { type: 'section', text: { type: 'mrkdwn', text: plainEnglish } },
          { type: 'context', elements: [{ type: 'mrkdwn', text: `RSI ${safeNum(live.rsi14, 1)} · MA50 ${safeNum(live.ma50)} · MA200 ${safeNum(live.ma200)}` }] },
          ...(news.length ? [{ type: 'section', text: { type: 'mrkdwn', text: '*Recent news*\n' + news.map(n => `• <${n.link}|${n.headline}> _(${n.source})_`).join('\n') } }] : []),
          { type: 'context', elements: [{ type: 'mrkdwn', text: `<https://finmate.app/docs/notifications|Read the guide →>  ·  FinMate ${windowLabel}` }] },
        ],
      },
    });
  }
  if (channels.length === 0) continue;
  if (seenUsers.has(user.id)) continue;
  seenUsers.add(user.id);
  rows.push({
    user_id: user.id, ticker, signal_3class: signal3,
    reason: plainEnglish, alert_window: alertWindow,
    channels,
    ...buildIds(user.id, holderPayload),
  });
}
return rows.map(r => ({ json: r }));

const sendRow = $('Build per-holder HTML + Slack').item.json;
const created = $input.item.json;
const alertId = Array.isArray(created) ? (created[0] && created[0].id) : created.id;
return [{ json: { ...sendRow, alert_id: alertId } }];

const rows = $input.all().map(i => i.json);
const out = [];
for (const row of rows) {
  for (const ch of (row.channels || [])) {
    out.push({ json: { ...row, ...ch } });
  }
}
return out;
